// Token 黑名单 / 主动撤销：内存 Map + TTL（虚拟时钟，输出确定）
const revoked = new Map();   // jti -> revokedUntil(秒)
let now = 1700000000;

function revoke(jti, ttlSec) { revoked.set(jti, now + ttlSec); }
function isRevoked(jti) {
  const until = revoked.get(jti);
  if (until === undefined) return false;
  if (now >= until) { revoked.delete(jti); return false; }   // TTL 到期自动清理
  return true;
}
function advance(sec) { now += sec; }

console.log('before_revoke=' + isRevoked('jti-100'));
revoke('jti-100', 300);
console.log('after_revoke=' + isRevoked('jti-100'));
advance(299);
console.log('at_299s=' + isRevoked('jti-100'));
advance(1);
console.log('at_300s=' + isRevoked('jti-100'));
console.log('map_size_after_ttl=' + revoked.size);

// 撤销列表的规模控制：只保留"仍在有效期内"的 jti，天然自清理
